import { Icon } from "@/registry/erbium/ui/icon";

import { InputGroup, InputGroupAddon, InputGroupInput } from "@/registry/erbium/ui/input-group";
import { Kbd } from "@/registry/erbium/ui/kbd";

export default function KbdInputGroupExample() {
  return (
    <div className="flex w-full max-w-xs flex-col gap-section">
      <InputGroup>
        <InputGroupInput placeholder="Search..." />
        <InputGroupAddon>
          <Icon name="search-01" />
        </InputGroupAddon>
        <InputGroupAddon align="inline-end">
          <Kbd hotkey="Mod+K" />
        </InputGroupAddon>
      </InputGroup>
    </div>
  );
}

import ExampleKbdInputGroup from "../examples/kbd-input-group";

const Example = () => (
  <div className="w-full max-w-2xl min-w-72 p-4">
    <ExampleKbdInputGroup />
  </div>
);

export default Example;
